@functools.lru_cache(maxsize=1)
def yc_data():
    refs = json.loads(zlib.decompress(base64.b85decode("".join(YC_REFERENCE_DATA_B85))).decode("utf-8"))
    rows = json.loads(zlib.decompress(base64.b85decode("".join(YC_HORSE_RUN_LOOKUP_B85))).decode("utf-8"))
    races_by_id = {}
    class_by_date = {}
    timed_by_horse = {}
    group = {}
    for date,rid,ci,dist,gi,cl,avg in refs:
        key = (YC_VENUES[ci], int(dist), YC_GOINGS[gi], YC_CLASSES[cl])
        group.setdefault(key, []).append((int(str(rid)[:4]), float(avg),int(date)))
        races_by_id[str(rid)] = (int(date), *key)
        ckey = (int(date),YC_VENUES[ci],int(dist),YC_GOINGS[gi])
        if int(date)>0:class_by_date.setdefault(ckey,set()).add(YC_CLASSES[cl])
    for date,name,ci,dist,clock10,cl in rows:
        key = (int(date),clean_text(name),YC_VENUES[ci],int(dist),int(clock10))
        timed_by_horse.setdefault(key,set()).add(YC_CLASSES[cl])
    return races_by_id,class_by_date,timed_by_horse,group

@functools.lru_cache(maxsize=60000)
def yc_clock_reference(year,course,distance,going,cl):
    """同年を一切参照せず、過去3年8戦／それ以前累積8戦の順で参照。"""
    try:
        year=int(year);distance=int(distance)
    except (TypeError,ValueError):
        return None
    if year<2018 or year>2027 or course not in YC_VENUES or cl not in YC_CLASSES:
        return None
    if going not in YC_GOINGS:
        return None
    allr=yc_data()[3].get((course,distance,going,cl),[])
    recent=[sec for y,sec,d in allr if year-3<=y<year]
    previous=[sec for y,sec,d in allr if y<year]
    if len(recent)>=8:
        return {"sec":round(float(np.mean(recent)),6),"n":len(recent),"method":"直近3暦年", "ref_year":year}
    if len(previous)>=8:
        return {"sec":round(float(np.mean(previous)),6),"n":len(previous),"method":"対象年以前全期間", "ref_year":year}
    return None

def yc_explicit_class(text):
    txt=clean_text(text)
    patterns=(
        ("G1",r"(?:G[ⅠI1]|GI)(?![0-9IV])|(?:Jpn[ⅠI1]|JpnI)(?![0-9IV])"),
        ("G2",r"(?:G[Ⅱ2]|GII)(?![0-9IV])|(?:Jpn[Ⅱ2]|JpnII)(?![0-9IV])"),
        ("G3",r"(?:G[Ⅲ3]|GIII)(?![0-9IV])|(?:Jpn[Ⅲ3]|JpnIII)(?![0-9IV])"),
        ("3勝",r"3勝クラス|1600万下|1600万円以下"),
        ("2勝",r"2勝クラス|1000万下|1000万円以下"),
        ("1勝",r"1勝クラス|500万下|500万円以下"),
        ("未勝利",r"未勝利"),
        ("新馬",r"新馬|メイクデビュー"),
        ("OP",r"オープン|\bOP\b|リステッド|\bL\b"),
    )
    found=[cl for cl,rx in patterns if re.search(rx,txt,re.I)]
    return found[0] if len(set(found))==1 else None

def yc_class_for_run(run,name):
    """公式ID／馬名＋実時計照合／明示クラス／クラス一意の順。曖昧なら欠損。"""
    date=run.get('date')
    if isinstance(date,datetime.datetime):date=date.date()
    if not isinstance(date,datetime.date):return None,'日付不明'
    day=int(date.strftime('%Y%m%d'))
    course=run.get('course');dist=run.get('distance');going=run.get('going')
    rid=str(run.get('race_id') or '')
    ridmeta=yc_data()[0].get(rid)
    if (ridmeta and ridmeta[1:4] == (course,dist,going)
        and (ridmeta[0]==day or (ridmeta[0]==0 and int(rid[:4])==date.year))):
        return ridmeta[4],'公式レースID'
    explicit=yc_explicit_class(run.get('source_text',''))
    sec=run.get('time')
    if sec is not None and np.isfinite(sec) and course in YC_VENUES and dist:
        exact=(day,clean_text(name),course,int(dist),int(round(float(sec)*10)))
        classes=yc_data()[2].get(exact,set())
        if len(classes)==1:
            matched=next(iter(classes))
            if explicit and matched!=explicit:return None,'明示クラスと過去走照合不一致'
            return matched,'過去走の馬名・開催日・時計照合'
    if explicit:
        return explicit,'走歴に明示されたクラス'
    classes=yc_data()[1].get((day,course,dist,going),set())
    if len(classes)==1:return next(iter(classes)),'同日・同条件のクラス一意'
    if len(classes)>1:return None,'同日に異なるクラスがあり確定不可'
    return None,'クラス不明（公式データ収録外を含む）'

def yc_evaluate_run(run,name,target_date):
    """当日以前のJRAダート走に限り条件別・年次基準と比較。"""
    date=run.get('date')
    if isinstance(date,datetime.datetime):date=date.date()
    if not isinstance(date,datetime.date):return None,'過去走日付不明'
    if not isinstance(target_date,datetime.date):return None,'今回の開催日不明'
    if date >= target_date:return None,'今回の開催日以降の成績'
    sec=run.get('time'); dist=run.get('distance');going=run.get('going');course=run.get('course')
    if sec is None or not np.isfinite(sec):return None,'過去走の実時計不明'
    if not dist or course not in YC_VENUES or going not in YC_GOINGS:return None,'コース・距離・馬場状態の不足'
    cl,origin=yc_class_for_run(run,name)
    if cl is None:return None,origin
    ref=yc_clock_reference(date.year,course,dist,going,cl)
    if ref is None:return None,'同条件の過去年時計が8レース未満'
    adv=(ref['sec']-float(sec))*1000.0/float(dist)
    med,spread,count=YC_TRAIN_SCALE.get(cl,YC_TRAIN_SCALE['全クラス'])
    score=float(np.clip(50+16*(adv-med)/spread,0,100))
    return {'date':date.isoformat(),'course':course,'distance':int(dist),'going':going,
            'class':cl,'class_provenance':origin,'actual_sec':round(float(sec),3),
            'top3_reference_sec':round(ref['sec'],3),'reference_n':ref['n'],
            'reference_method':ref['method'],'adv_sec1000':round(adv,4),
            'year_clock_score':round(score,2),'scale_class_n':count},None


# 従来5要素の比較値だけ残す（2026/11/08版との比較）。
LEGACY_NEW_WEIGHTS = {"time": .25, "last3f": .20, "margin": .20,
                      "distance": .20, "going": .15}
# 新AI: 年次補正時計55%、距離15%、馬場10%、騎手相性20%。
# 上がり3F・着差は独立した加点を廃止。時計と重複させない。
NEW_WEIGHTS = {"time": .55, "distance": .15, "going": .10, "jockey": .20}
NEW_AI_VERSION = "YEARCLOCK55_DISTANCE15_GOING10_JOCKEY_HORSESTYLE20_20261111v3"

def dirt_model_before_yearclock(horses, target_distance=None, target_going=None):
    runs_all = [r for h in horses for r in h.get("dirt_histories", [])]
    def normalized_time(r):
        if r.get("time") is None or r.get("going") not in GOING_SEC_PER_1000M:
            return None
        return r["time"] - GOING_SEC_PER_1000M[r["going"]] * r["distance"] / 1000

    reference = {}
    for r in runs_all:
        key = (r.get("course"), r["distance"])
        reference.setdefault(key, []).append(normalized_time(r))
    scales = {key: robust_scale(vals) for key, vals in reference.items()}

    for h in horses:
        components = {k: [] for k in LEGACY_NEW_WEIGHTS}
        for r in h.get("dirt_histories", []):
            dist = r["distance"]
            t = normalized_time(r)
            ref = scales.get((r.get("course"), dist))
            if ref and t is not None:
                med, spread, sign = ref
                components["time"].append(float(np.clip(50 + 16*sign*(t-med)/spread, 0, 100)))
            finals = [q["last3f"] for q in runs_all if abs(q["distance"]-dist) <= 100 and q.get("last3f") is not None]
            fref = robust_scale(finals)
            if fref and r.get("last3f") is not None:
                med, spread, sign = fref
                components["last3f"].append(float(np.clip(50 + 16*sign*(r["last3f"]-med)/spread, 0, 100)))
            # 着差は勝ち馬との秒差。負値（勝利時の2着馬との差）は0扱い。
            if r.get("margin") is not None:
                components["margin"].append(float(np.clip(90 - max(0, r["margin"]) * 22, 0, 100)))
            if target_distance:
                closeness = max(0., 1. - abs(dist-target_distance)/800.)
                if r.get("rank") and r.get("field", 0) > 1:
                    finish = (r["field"]-r["rank"])/(r["field"]-1)
                    components["distance"].append(float(100*(.5*closeness+.5*finish)*closeness))
            # 馬場適性は同じ馬場状態での実績に限る。対象馬場が不明なら採点しない。
            if target_going and r.get("going") == target_going and r.get("rank") and r.get("field", 0) > 1:
                components["going"].append(float(np.clip(100*(r["field"]-r["rank"])/(r["field"]-1), 0, 100)))
        values = {k: round(float(np.mean(v)),2) if v else None for k,v in components.items()}
        present = [k for k,v in values.items() if v is not None]
        total = sum(LEGACY_NEW_WEIGHTS[k] for k in present)
        # 欠損項目の重みを無条件に再配分しない。タイム/上がりの片方と着差が必要。
        required = values["margin"] is not None and (values["time"] is not None or values["last3f"] is not None)
        h["ai_score"] = round(sum(LEGACY_NEW_WEIGHTS[k]*values[k] for k in present)/total, 2) if required and total >= .45 else None
        h.update({f"{k}_score": values[k] for k in LEGACY_NEW_WEIGHTS})
        h["evidence_coverage"] = round(100*total, 1)
    return horses




def _jm_name(value):
    """空欄や欠損を名前として扱わず、表記の空白だけ正規化。"""
    if value is None:return ""
    v=unicodedata.normalize("NFKC",str(value)).strip()
    if v.lower() in ("none","nan","null","-","—"):return ""
    # 出走表では減量記号や「乗替」の装飾がつく場合があるため、名前からのみ除去する。
    v = re.sub(r"^(?:騎手[:：]|乗替[:：]|乗り替わり[:：])", "", v)
    v = re.sub(r"^[☆▲△◇★◎○]+", "", v)
    v = re.sub(r"[（(](?:替|乗替|減量)[）)]$", "", v)
    return re.sub(r"\s+","",v)


def _jm_histories(horse):
    """能力指数は直近4走のまま。騎手評価に限り別保存の全過去走を参照する。"""
    full = horse.get('jockey_full_dirt_histories')
    return full if isinstance(full, list) else (horse.get('dirt_histories') or [])


def _jm_before(run,target_date):
    dt=run.get("date")
    if isinstance(dt,datetime.datetime):dt=dt.date()
    if isinstance(dt,str):
        try:dt=datetime.date.fromisoformat(dt[:10])
        except ValueError:return False
    return isinstance(dt,datetime.date) and isinstance(target_date,datetime.date) and dt < target_date


def _jm_style_database(horses,target_date,reference_horses=None):
    """開催前に分かるレース当日出走馬の過去騎乗だけから騎手の4角位置傾向を計測。
    同一の過去走が複数レースから入っても1件にする。騎手名と4角位置は必須。
    """
    pool=list(horses)
    if reference_horses is not None:
        pool.extend(reference_horses)
    for race in globals().get('all_loaded_races',[]) or []:
        if race.get('race_date')==target_date:
            pool.extend(race.get('horses') or [])
    by_rider={};seen=set()
    for h in pool:
        ident=str(h.get('horse_id') or h.get('name') or '')
        for r in _jm_histories(h):
            if not _jm_before(r,target_date):continue
            jockey=_jm_name(r.get('jockey'))
            field=r.get('field'); corner=r.get('corner_pos')
            if not jockey or not isinstance(field,(int,float)) or not isinstance(corner,(int,float)) or field < 3 or not (1<=corner<=field):continue
            ride_key=(ident,str(r.get('date')),str(r.get('race_id') or ''),r.get('course'),r.get('distance'))
            if ride_key in seen:continue
            seen.add(ride_key)
            norm=(corner-1)/(field-1)  # 0=4角先頭 1=最後方
            by_rider.setdefault(jockey,[]).append((norm,ident))
    result={}
    for name,vals in by_rider.items():
        if len(vals)<5 or len({h for _,h in vals})<3:
            continue  # 騎乗実例が少ない騎手の「タイプ」は作らない
        mean=float(np.mean([p for p,_ in vals]))
        typ='先行傾向' if mean<.38 else ('中団傾向' if mean<.67 else '後方傾向')
        result[name]={'position':mean,'type':typ,'rides':len(vals),'horses':len({h for _,h in vals})}
    # 外部騎乗履歴は対象レースの日付より前のレースだけを集計。公開ページの
    # 「2026年通算成績」を過去日付の予測に混ぜることはしない。
    try:
        ext_state = st.session_state.get("jm_external_profiles", {})
        ext_day = ext_state.get(target_date.isoformat(), {}) if isinstance(target_date, datetime.date) else {}
        for name, profile in ext_day.items():
            vals = []
            for r in profile.get("rides", []):
                if not _jm_before(r, target_date):
                    continue
                field, corner = r.get("field"), r.get("corner_pos")
                if not isinstance(field, (int, float)) or not isinstance(corner, (int, float)):
                    continue
                if field < 3 or not (1 <= corner <= field):
                    continue
                horse_name = _jm_name(r.get("horse_name"))
                if horse_name:
                    vals.append(((corner - 1)/(field - 1), horse_name))
            different = len({h for _, h in vals})
            if len(vals) >= 5 and different >= 3:
                m = float(np.mean([v for v, _ in vals]))
                t = '先行傾向' if m < .38 else ('中団傾向' if m < .67 else '後方傾向')
                # 同数以上の独立騎乗例が揃う場合にだけ公開履歴の評価を優先する。
                if name not in result or len(vals) >= result[name]['rides']:
                    result[name] = {'position': m, 'type': t, 'rides': len(vals),
                                    'horses': different, 'source': 'ウマピア騎手別履歴（芝ダ混合・開催前のみ）'}
    except (ValueError, TypeError, AttributeError, KeyError):
        pass
    return result



def _jm_horse_position_profile(horse, target_date, target_distance=None):
    """馬自身の発走前ダート走歴から4角位置の傾向を計算する。

    騎手名が欠けていても、頭数・通過位置・日付があれば計算可能。
    指数と独立して直近最大8走を使い、近走・好走・今回距離への近さを弱く重視。
    位置の大小は「前方ほど小さい」に正規化。
    """
    eligible = []
    for run in _jm_histories(horse):
        if not _jm_before(run, target_date):
            continue
        field, corner = run.get('field'), run.get('corner_pos')
        try:
            field, corner = float(field), float(corner)
        except (TypeError, ValueError):
            continue
        if field < 3 or not (1 <= corner <= field):
            continue
        day = run.get('date')
        if isinstance(day, str):
            try:
                day = datetime.date.fromisoformat(day[:10])
            except ValueError:
                continue
        if isinstance(day, datetime.datetime):
            day = day.date()
        if not isinstance(day, datetime.date):
            continue
        eligible.append((day, run, (corner - 1)/(field - 1)))
    eligible.sort(key=lambda z: z[0], reverse=True)
    eligible = eligible[:8]
    if len(eligible) < 2:
        return None
    positions, weights, good_positions, good_weights = [], [], [], []
    for day, run, pos in eligible:
        days_old = max(0, (target_date - day).days)
        weight = 1.0 / (1.0 + days_old/550.)
        try:
            d, target = float(run.get('distance')), float(target_distance)
            if abs(d-target) <= 400:
                weight *= 1.20
            elif abs(d-target) >= 800:
                weight *= 0.80
        except (TypeError, ValueError):
            pass
        rank = run.get('rank')
        try:
            good = 1 <= float(rank) <= 3
        except (TypeError, ValueError):
            good = False
        if good:
            weight *= 1.15
            good_positions.append(pos)
            good_weights.append(weight)
        positions.append(pos)
        weights.append(weight)
    all_mean = float(np.average(positions, weights=weights))
    # 好走時の位置も参考にする。ただし好走1例で全てを塗り替えない。
    if len(good_positions) >= 2:
        good_mean = float(np.average(good_positions, weights=good_weights))
        mean = .70*all_mean + .30*good_mean
    else:
        good_mean = None
        mean = all_mean
    typ = '先行傾向' if mean < .38 else ('中団傾向' if mean < .67 else '後方傾向')
    return {'position':mean, 'type':typ, 'runs':len(eligible),
            'good_runs':len(good_positions), 'good_position':good_mean}


def _jm_jockey_score(horse,target_date,style_db,target_distance=None):
    """馬自身の位置取りと今回の騎手の傾向を直接照合する。

    以前の実装は「過去走の騎手名が全件欠損」だと即座に中立点へ
    戻していた。ここではその早期終了を廃止する。
    """
    now=_jm_name(horse.get('jockey'))
    rider=style_db.get(now,{}) if now else {}
    horse_style=_jm_horse_position_profile(horse,target_date,target_distance)
    details={
        'jockey_now':now or None,
        'jockey_type':rider.get('type'),
        'jockey_style_position':round(rider['position'],3) if rider.get('position') is not None else None,
        'jockey_style_rides':rider.get('rides',0),
        'jockey_similarity':None,
        'jockey_scoring_method':'騎手名未取得',
        'jockey_good_rider':None,
        'jockey_evidence_runs':0,
        'horse_position_type':horse_style.get('type') if horse_style else None,
        'horse_position_run_count':horse_style.get('runs',0) if horse_style else 0,
        'horse_position_good_count':horse_style.get('good_runs',0) if horse_style else 0,
        'horse_position_mean':round(horse_style['position'],3) if horse_style else None,
    }
    if not now:
        return None,details
    runs=[r for r in _jm_histories(horse) if _jm_before(r,target_date)]
    same=[]
    for r in runs:
        if _jm_name(r.get('jockey')) != now:
            continue
        try:
            rank, field = float(r.get('rank')), float(r.get('field'))
            if field > 1 and 1 <= rank <= field:
                same.append(100*(field-rank)/(field-1))
        except (TypeError, ValueError):
            pass
    same_score = ((150+sum(same))/(3+len(same))) if same else None
    style_score=None
    if horse_style is not None and rider.get('position') is not None:
        similarity=max(0.,1. - abs(float(rider['position'])-horse_style['position'])/.58)
        # 相性が本当に着順を改善するかは未検証。過剰な加減点を避ける。
        reliability=min(1.,(horse_style['runs']/4.)**.5)
        if rider.get('rides',0) < 10:
            reliability *= .80
        style_score=50. + 30.*(similarity-.5)*reliability  # 原則35〜65点
        details['jockey_similarity']=round(similarity,3)
        details['jockey_evidence_runs']=horse_style['runs']
    if style_score is not None and same_score is not None:
        same_weight=min(.80,.50 + .08*len(same))
        score=same_weight*same_score + (1-same_weight)*style_score
        method='同騎手の過去実績＋馬と今回騎手の4角位置相性'
    elif style_score is not None:
        score=style_score
        method='馬の過去4角位置×今回騎手の騎乗傾向'
    elif same_score is not None:
        score=same_score
        method='同騎手の過去ダート実績（騎手タイプ未照合）'
    else:
        if horse_style is None:
            method='馬の過去4角位置が2走未満で相性評価不可'
        elif rider.get('position') is None:
            method='今回騎手の騎乗傾向データ不足'
        else:
            method='騎手相性の評価根拠不足'
        details['jockey_scoring_method']=method
        return None,details
    good_riders=[]
    for r in runs:
        try:
            good=1 <= float(r.get('rank')) <= 3
        except (TypeError,ValueError):
            good=False
        rider_name=_jm_name(r.get('jockey'))
        if good and rider_name and rider_name not in good_riders:
            good_riders.append(rider_name)
    details['jockey_good_rider']=','.join(good_riders[:8]) if good_riders else None
    details['jockey_scoring_method']=method
    return round(float(np.clip(score,0.,100.)),2),details

def dirt_model(horses, target_distance=None, target_going=None, target_date=None, jockey_reference_horses=None):
    """新AI: 年次補正時計55 / 距離15 / 馬場10 / 騎手相性20。
    上がりと着差の単独加点は廃止し、比較用の旧指数は保持する。
    """
    dirt_model_before_yearclock(horses,target_distance,target_going)
    style_db=_jm_style_database(horses,target_date,reference_horses=jockey_reference_horses)
    for horse in horses:
        horse['ai_score_before_yearclock']=horse.get('ai_score')
        horse['time_score_before_yearclock']=horse.get('time_score')
        evaluations=[];reasons=[]
        for past_run in horse.get('dirt_histories',[]):
            item,reason=yc_evaluate_run(past_run,horse.get('name',''),target_date)
            if item:evaluations.append(item)
            elif reason:reasons.append(reason)
        time_value=round(float(np.mean([z['year_clock_score'] for z in evaluations])),2) if evaluations else None
        # 旧・年次補正25%版も変更前比較用の別欄に保持（購入モデルへは不使用）。
        old_values={k:(time_value if k=='time' else horse.get(k+'_score')) for k in LEGACY_NEW_WEIGHTS}
        old_present=[k for k,val in old_values.items() if val is not None and np.isfinite(val)]
        old_total=sum(LEGACY_NEW_WEIGHTS[k] for k in old_present)
        old_ready=(old_values.get('margin') is not None and
                   (old_values.get('time') is not None or old_values.get('last3f') is not None))
        horse['ai_score_yearclock25_before']=(round(sum(LEGACY_NEW_WEIGHTS[k]*old_values[k] for k in old_present)/old_total,2)
                                             if old_ready and old_total>=.45 else None)
        horse['time_score']=time_value
        horse['year_clock_time_score']=time_value
        horse['year_clock_evidence']=evaluations
        horse['year_clock_run_count']=len(evaluations)
        horse['year_clock_adv_sec1000_mean']=(round(float(np.mean([z['adv_sec1000'] for z in evaluations])),3) if evaluations else None)
        horse['year_clock_adv_sec1000_best']=(round(float(max(z['adv_sec1000'] for z in evaluations)),3) if evaluations else None)
        horse['year_clock_unmatched_reasons']=list(dict.fromkeys(reasons))
        jockey_val,j_details=_jm_jockey_score(horse,target_date,style_db,target_distance)
        horse.update(j_details)
        horse['jockey_score']=jockey_val
        horse['jockey_score_applied']=50.0 if jockey_val is None else jockey_val
        # 騎手名・根拠が無い場合も指数内では50点とするが、推測した実測値とは区別する。
        # 直近4走の距離・馬場適性は元の採点方法を維持。
        values={k:horse.get(k+'_score') for k in NEW_WEIGHTS}
        present=[k for k,val in values.items() if val is not None and np.isfinite(val)]
        coverage=sum(NEW_WEIGHTS[k] for k in present)
        horse['evidence_coverage']=round(100*coverage,1)
        horse['jockey_score_used_neutral']=jockey_val is None
        # 時計55%は必須。分からない時計を他の要素の高得点で補完しない。
        if time_value is None:
            horse['ai_score']=None
            horse['new_ai_missing_reason']='年次補正時計の根拠不足'
        else:
            # 不明な適性・騎手には中立50点を使用。20%を他項目に再配分しない。
            horse['ai_score']=round(sum(NEW_WEIGHTS[k]*float(values[k] if k in present else 50.0)
                                         for k in NEW_WEIGHTS),2)
            horse['new_ai_missing_reason']='' if coverage==1.0 else '一部要素は中立50点で暫定評価'
        horse['year_clock_model_version']=YC_VERSION
        horse['new_ai_model_version']=NEW_AI_VERSION
    return horses


def heading_date(raw):
    # Some exported JRA headings lose the leading "2" in "2026年".
    # Only repair the exact three-digit year 026, never arbitrary years.
    normalized = clean_text(raw)
    normalized = re.sub(r"(?<!\d)026年(?=\s*\d{1,2}月)", "2026年", normalized)
    m = re.search(r"(20\d{2})年\s*(\d{1,2})月\s*(\d{1,2})日", normalized)
    if not m:
        m = re.search(r"(20\d{2})[-/](\d{1,2})[-/](\d{1,2})", normalized)
    if not m:
        return None
    try:
        return datetime.date(*map(int, m.groups()))
    except ValueError:
        return None



def parse_prior_history_date(value):
    """成績文字列から実開催日を取得。不明な履歴は予想に使わない。"""
    value = clean_text(value)
    m = re.search(r"(20\d{2})\s*(?:年|[-/])\s*(\d{1,2})\s*(?:月|[-/])\s*(\d{1,2})\s*日?", value)
    if not m:
        return None
    try:
        return datetime.date(*(int(x) for x in m.groups()))
    except ValueError:
        return None

def parse_sheet_rows(rows, day_label, sheet_name=""):
    races = []
    current = None
    columns = None

    def finish():
        nonlocal current
        if current and current["horses"]:
            course = current["course"]
            number = current["race_no"]
            name = f"{course} {number}R" if course else f"開催場不明 {number}R"
            if current["race_title"]:
                name += f" {current['race_title']}"
            current["race_name"] = name
            current["identified"] = bool(course and number)
            current["day_label"] = day_label
            heading = current.get("heading_raw", "")
            current["race_date"] = heading_date(heading) or heading_date(sheet_name)
            surface_text = heading + "\n" + "\n".join(current.get("race_info", [])[:4])
            surface_text = unicodedata.normalize("NFKC", surface_text)
            # JRA race headings use "コース：1,400メートル（ダート・左）".
            # Earlier detection only recognized "ダート1400" and missed Tokyo races.
            # Determine the surface from the current race's course clause first.
            course_clause = re.search(r"コース\s*[:：]\s*[\d,，]+\s*(?:メートル|m)\s*[（(]\s*(ダート|芝)", surface_text)
            dirt_match = re.search(r"(?:ダート|ダ)\s*(\d{3,4})\s*(?:m|メートル)?", surface_text, re.I)
            dirt_match_rev = re.search(r"(\d{3,4})\s*(?:m|メートル)?\s*(?:ダート|ダ)(?![ァ-ン])", surface_text, re.I)
            turf_match = re.search(r"(?:芝|ターフ)\s*(\d{3,4})|(\d{3,4})\s*(?:m)?\s*芝", surface_text, re.I)
            dist_match = dirt_match or dirt_match_rev
            dirt_marker = re.search(r"(?<![ァ-ン一-龥])ダート(?![ァ-ン])|(?<![ァ-ン一-龥])ダ(?=\s|\d{3,4}|$)", surface_text)
            turf_marker = re.search(r"(?<![ァ-ン一-龥])芝(?=\s|\d{3,4}|$)", surface_text)
            target_distance = int(dist_match.group(1)) if dist_match else None
            if target_distance is None and dirt_marker:
                distance_candidates = re.findall(r"(?<!\d)(?:1000|1150|1200|1300|1400|1600|1700|1800|1900|2000|2100|2400|2500)(?!\d)", surface_text)
                if len(set(distance_candidates)) == 1:
                    target_distance = int(distance_candidates[0])
            current["target_distance"] = target_distance
            if course_clause:
                current["is_dirt_race"] = course_clause.group(1) == "ダート"
                current["surface_conflict"] = False
                if target_distance is None:
                    distance_from_clause = re.search(r"コース\s*[:：]\s*([\d,，]+)", surface_text)
                    if distance_from_clause:
                        current["target_distance"] = int(re.sub(r"[,，]", "", distance_from_clause.group(1)))
            else:
                current["is_dirt_race"] = bool(dirt_match or dirt_match_rev or dirt_marker) and not bool(turf_match or turf_marker)
                current["surface_conflict"] = bool((dirt_match or dirt_match_rev or dirt_marker) and (turf_match or turf_marker))
            current["surface_diagnostic"] = surface_text[:240]
            going_match = re.search(r"(?:ダート|ダ)\s*(?:\d{3,4}\s*m?\s*)?(稍重|不良|良|重)", surface_text)
            current["target_going"] = going_match.group(1) if going_match else None
            dirt_model(current["horses"], target_distance, None, current.get("race_date"))
            odds_list = [h.get("odds") for h in current["horses"]]
            if odds_list and all(x is not None for x in odds_list):
                for h in current["horses"]:
                    h["pop_rank"] = 1 + sum(x < h["odds"] for x in odds_list)
            races.append(current)
        current = None

    for raw in rows:
        cells = [clean_text(x) for x in raw]
        if not any(cells):
            continue
        first = cells[0]
        if first and ("発走時刻" in first or "レース" in first):
            heading = parse_race_heading(first, sheet_name)
            if heading:
                finish()
                current = {**heading, "horses": [], "heading_raw": " ".join(cells),
                           "race_info": [], "sheet_name": sheet_name,
                           "race_date": heading_date(" ".join(cells)) or heading_date(sheet_name),
                           "除外した当日以降の履歴": 0, "除外した日付不明履歴": 0}
                columns = None
                continue
        if any("馬番" in c for c in cells) and any("馬名" in c for c in cells):
            columns = {
                "horse": next(i for i, c in enumerate(cells) if "馬番" in c),
                "name": next(i for i, c in enumerate(cells) if "馬名" in c),
                "previous": [i for i, c in enumerate(cells) if re.search(r"前走|前々走|[34]走前", c)],
                "odds": next((i for i,c in enumerate(cells) if c == "単勝" or c.startswith("単勝オッズ")), None),
                "jockey": next((i for i,c in enumerate(cells) if c in ("騎手","ジョッキー") or c.startswith("騎手名")), None),
            }
            continue
        if current is not None and columns is None:
            current.setdefault("race_info", []).append(" ".join(cells))
        if current is None or columns is None:
            continue
        hi, ni, previous_indices = columns["horse"], columns["name"], columns["previous"]
        if max(hi, ni) >= len(cells):
            continue
        # Some exported workbooks have an entirely empty 馬番 column.
        # Preserve the horse rows for analysis, but never regard an inferred
        # sequential position as a verified betting horse number.
        inferred_number = False
        try:
            horse_no = int(float(cells[hi]))
            if not 1 <= horse_no <= 18 or float(cells[hi]) != horse_no:
                continue
        except (ValueError, TypeError):
            if not cells[ni] or not previous_indices:
                continue
            if not any(i < len(cells) and cells[i] for i in previous_indices):
                continue
            horse_no = len(current["horses"]) + 1
            if horse_no > 18:
                continue
            inferred_number = True
        if any(h["horse_no"] == horse_no for h in current["horses"]):
            continue
        if inferred_number:
            current["horse_numbers_unverified"] = True
        field = cells[ni]
        name = field.split("\n")[0].strip()
        if not name:
            continue
        odds_match = ODDS_PATTERN.search(field)
        odds_idx = columns.get("odds")
        jockey_idx = columns.get("jockey")
        current_jockey = clean_text(cells[jockey_idx]) if jockey_idx is not None and jockey_idx < len(cells) else ""
        odds = numeric_odds(cells[odds_idx]) if odds_idx is not None and odds_idx < len(cells) else (float(odds_match.group(1)) if odds_match else None)
        popularity = int(odds_match.group(2)) if odds_match else None

        histories = [cells[i] for i in previous_indices if i < len(cells) and cells[i]]
        # 発走前の履歴だけ。今回の開催日と同日・未来・日付不明は指数へ渡さない。
        valid_histories = []
        cutoff = current.get("race_date")
        for h in histories:
            run_date = parse_prior_history_date(h)
            if run_date is None or not isinstance(cutoff, datetime.date):
                current["除外した日付不明履歴"] += 1
            elif run_date >= cutoff:
                current["除外した当日以降の履歴"] += 1
            else:
                valid_histories.append(h)
        previous = valid_histories[0] if valid_histories else ""
        time_score, last3f_score = parse_horse_history(previous)
        history_scores = []
        dirt_runs = 0
        for history in valid_histories:
            finish_match = re.search(r"(?<!\d)(\d{1,2})着", history)
            field_size = re.search(r"(?<!\d)(\d{1,2})頭", history)
            is_dirt = bool(re.search(r"\d{3,4}\s*ダ", history))
            if is_dirt:
                dirt_runs += 1
            if finish_match and field_size:
                rank, field = int(finish_match.group(1)), int(field_size.group(1))
                if field >= 2 and 1 <= rank <= field:
                    percentile = 100 * (field - rank) / (field - 1)
                    history_scores.append((percentile, is_dirt))
        weighted = [(v, 1.0 if is_dirt else 0.65) for v, is_dirt in history_scores]
        relative_score = (sum(v * w for v, w in weighted) / sum(w for _, w in weighted)) if weighted else None
        dirt_results = [v for v, is_dirt in history_scores if is_dirt]
        dirt_score = sum(dirt_results) / len(dirt_results) if dirt_results else None
        current["horses"].append({
            "horse_no": horse_no, "name": name,
            "jockey": _jm_name(current_jockey),
            "horse_no_verified": not inferred_number,
            "pop_rank": popularity, "odds": odds,
            "time_index": time_score, "last3f_index": last3f_score,
            "track_aptitude": 75.0,
            "history_count": len(valid_histories),
            "dirt_runs": dirt_runs,
            "relative_score": relative_score,
            "dirt_score": dirt_score,
            "dirt_histories": [r for r in (parse_dirt_run(h) for h in valid_histories) if r],
        })
    finish()
    return races


def summarize_history_exclusions(races):
    return {
        "当日以降": sum(int(r.get("除外した当日以降の履歴", 0)) for r in races),
        "日付不明": sum(int(r.get("除外した日付不明履歴", 0)) for r in races),
    }


def parse_workbook_bytes(data, day_label):
    from openpyxl import load_workbook
    workbook = load_workbook(io.BytesIO(data), read_only=True, data_only=True)
    try:
        races = []
        for sheet in workbook.worksheets:
            races.extend(parse_sheet_rows(sheet.values, day_label, sheet.title))
        return races
    finally:
        workbook.close()


SOURCES = [
    {"id": "14Zn-qUtrbhvNIXJXfNoB8hLfFXLzzeRf-jI3qBDZI_Q", "day_label": "土曜日開催"},
    {"id": "1oI_Z6cqjDjQP9C81WsLJ5GgfTMqNw7mbiH2N9N9b780", "day_label": "日曜日開催"},
]


def download_workbook(file_id):
    candidates = [
        ("Googleスプレッドシート形式", f"https://docs.google.com/spreadsheets/d/{file_id}/export?format=xlsx"),
        ("Google DriveのExcelファイル", f"https://drive.google.com/uc?export=download&id={file_id}"),
    ]
    failures = []
    for label, url in candidates:
        try:
            request = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0", "Accept": "*/*"})
            with urllib.request.urlopen(request, timeout=35) as response:
                content = response.read()
            if not zipfile.is_zipfile(io.BytesIO(content)):
                preview = content[:200].decode("utf-8", errors="replace").replace("\n", " ")
                failures.append(f"{label}: Excelではない応答 ({len(content)} bytes, {preview[:90]!r})")
                continue
            with zipfile.ZipFile(io.BytesIO(content)) as z:
                if "xl/workbook.xml" not in z.namelist():
                    failures.append(f"{label}: ExcelブックではないZIP")
                    continue
            return content, label
        except HTTPError as exc:
            failures.append(f"{label}: HTTP {exc.code} {exc.reason}")
        except (URLError, TimeoutError, OSError) as exc:
            failures.append(f"{label}: 通信エラー {type(exc).__name__}: {exc}")
        except Exception as exc:
            failures.append(f"{label}: {type(exc).__name__}: {exc}")
    raise RuntimeError(" / ".join(failures))


@st.cache_data(ttl=60)
def load_races_from_google_drive():
    races, errors, diagnostics = [], [], []
    for source in SOURCES:
        day = source["day_label"]
        try:
            content, method = download_workbook(source["id"])
            parsed = parse_workbook_bytes(content, day)
            races.extend(parsed)
            diagnostics.append(f"{day}: {method}から {len(parsed)} レースを取得 / 馬番空欄レース {sum(bool(r.get('horse_numbers_unverified')) for r in parsed)}件")
            if not parsed:
                errors.append(f"{day}: Excelは取得できましたが、レースを解析できませんでした")
        except Exception as exc:
            errors.append(f"{day}: {exc}")
    return races, errors, diagnostics


# ============================================================
# スマートフォンから直接取得（Colab不要）
# netkeiba公開ページをStreamlitサーバー側で取得する。
# 旧AI・新AIのスコア関数は改変しない。
# ============================================================

def mobile_browser_session():
    import requests
    session = requests.Session()
    session.headers.update({
        "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                       "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"),
        "Accept-Language": "ja-JP,ja;q=0.9,en;q=0.6",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    })
    return session


def mobile_get_soup(url, session=None, tries=3):
    import requests
    from bs4 import BeautifulSoup
    session = session or mobile_browser_session()
    failures = []
    for attempt in range(1, tries + 1):
        try:
            response = session.get(url, timeout=(8, 23), allow_redirects=True)
            response.raise_for_status()
            if len(response.content) < 250:
                raise RuntimeError("HTML本文が短すぎます")
            soup = BeautifulSoup(response.content, "html.parser")
            body_text = soup.get_text(" ", strip=True)[:500].lower()
            if any(t in body_text for t in ("access denied", "captcha", "アクセスが集中")):
                raise RuntimeError("提供元がアクセスを制限しています")
            return soup
        except requests.HTTPError as exc:
            status = getattr(exc.response, "status_code", None)
            failures.append(f"{attempt}回目 HTTP {status}")
            if status in (403, 404):
                break
        except Exception as exc:
            failures.append(f"{attempt}回目 {type(exc).__name__}: {str(exc)[:120]}")
        if attempt < tries:
            time.sleep(min(attempt * 1.0, 2.5))
    raise RuntimeError(" / ".join(failures))


# ====================================================================
# 騎手情報の公開補助資料：ウマピア（騎乗履歴）と競馬ラボ（成績照合）
# ※公開ページの取得失敗時は既存騎手履歴へフォールバック。アクセス制限は回避しない。
# ※当年累計成績は発走前の過去時点を再現できないため能力点に使用しない。
# ※騎手タイプは4角位置からの傾向であり手腕や因果効果ではない。
# ====================================================================
JM_PUBLIC_VERSION = "umapia-rides-stats-fallback-horse-style-20261111-v2"
JM_PUBLIC_MAX_RIDERS = 24


def jm_public_umapia_index(soup):
    """公開騎手一覧の各リンクから氏名と内部IDを取得（年のURLで固定IDを推測しない）。"""
    found = {}
    for a in soup.find_all('a', href=True):
        m = re.search(r'/search/jockeys/(\d+)(?:/?(?:\?|$))', a['href'])
        if not m:
            continue
        nm = _jm_name(a.get_text(' ', strip=True))
        if not nm or len(nm)>28:
            continue
        found[nm] = m.group(1)
    if len(found)<5:
        raise RuntimeError('ウマピアの騎手リンクが見つかりません（ページ変更の可能性）')
    return found


def jm_public_umapia_rides(soup, name):
    """騎手別競走成績表。元レコードに通過順位、頭数、馬名、日付を要求する。"""
    rides = []
    seen = set()
    for tr in soup.find_all('tr'):
        tds = tr.find_all('td', recursive=False)
        if len(tds)<18:
            continue
        cells = [td.get_text(' ', strip=True) for td in tds]
        dm=re.fullmatch(r'(20\d{2})/(\d{1,2})/(\d{1,2})', cells[0])
        if not dm:
            continue
        try:
            dt=datetime.date(int(dm.group(1)),int(dm.group(2)),int(dm.group(3)))
            field=int(re.sub(r'[^\d]', '', unicodedata.normalize('NFKC',cells[5])))
            rank=int(re.sub(r'[^\d]', '', unicodedata.normalize('NFKC',cells[10])))
            raw_corner=unicodedata.normalize('NFKC',cells[17])
            positions=[int(x) for x in re.findall(r'\d+', raw_corner)]
            corner=positions[-1] if positions else None
            horse_name=_jm_name(cells[11])
        except (ValueError,TypeError,IndexError):
            continue
        if not horse_name or not (3<=field<=18 and 1<=rank<=field):
            continue
        # 競馬場表記例: 5京都2 / 3東京4。地方はスタイル混入を防ぐため対象外。
        venue=unicodedata.normalize('NFKC',cells[1])
        if not any(course in venue for course in TRIO_VENUE_CODES):
            continue
        if corner is None or not (1<=corner<=field):
            continue
        key=(dt,venue,cells[3],horse_name)
        if key in seen:
            continue
        seen.add(key)
        rides.append({'date':dt,'jockey':_jm_name(name),'horse_name':horse_name,
                      'field':field,'corner_pos':corner,'rank':rank,
                      'course':venue,'distance':cells[13],
                      'race_id':f'{dt.isoformat()}:{venue}:{cells[3]}',
                      'source':'ウマピア'})
    return rides



def jm_public_umapia_leading(soup):
    """ウマピア騎手リーディングの当年成績を表示用に読む。

    着順・騎乗数は集計済み値であり、モデル採点には使用しない。
    """
    out={}
    for tr in soup.find_all('tr'):
        tds=tr.find_all('td',recursive=False)
        if len(tds)<10:
            continue
        cells=[unicodedata.normalize('NFKC', td.get_text(' ',strip=True)) for td in tds]
        nm=_jm_name(cells[1])
        try:
            a,b,c=[int(cells[k].replace(',','')) for k in (2,3,4)]
            n=int(cells[6].replace(',',''))
        except (IndexError,ValueError):
            continue
        if nm and n>0 and n>=a+b+c:
            out[nm]={'騎乗数':n,'1着':a,'2着':b,'3着':c,
                     '複勝率':round(100*(a+b+c)/n,1),'出典':'ウマピア'}
    if len(out)<5:
        raise RuntimeError('ウマピアのリーディング表を取得できませんでした')
    return out


def jm_public_keibalab_leading(soup):
    """競馬ラボのリーディング情報（取得できれば診断・照合のみ）。"""
    result={}
    for tr in soup.find_all('tr'):
        cells=[td.get_text(' ',strip=True) for td in tr.find_all(['td','th'], recursive=False)]
        if len(cells)<9:
            continue
        # 順位,騎手名,所属,1着,2着,3着,着外,騎乗回数,勝率,...
        nm=_jm_name(cells[1])
        try:
            n=int(cells[7].replace(',',''))
            a,b,c=[int(cells[k].replace(',','')) for k in (3,4,5)]
        except (IndexError, ValueError):
            continue
        if nm and n>=a+b+c>=0:
            result[nm]={'騎乗数':n,'1着':a,'2着':b,'3着':c,'複勝率':round(100*(a+b+c)/n,1) if n else 0.,'出典':'競馬ラボ'}
    if len(result)<5:
        raise RuntimeError('競馬ラボ騎手成績テーブル未検出（アクセス制限・仕様変更）')
    return result


def jm_public_get_soup(url):
    """外部補助サイト用の短時間アクセス。403/429は回避せずエラーとして記録。"""
    from bs4 import BeautifulSoup
    import requests
    session=mobile_browser_session()
    response=session.get(url,timeout=(4,9),allow_redirects=True)
    response.raise_for_status()
    if len(response.content)<200:
        raise RuntimeError('公開ページ本文が短すぎます')
    soup=BeautifulSoup(response.content,'html.parser')
    summary=soup.get_text(' ',strip=True)[:500].lower()
    if any(w in summary for w in ('captcha','access denied','アクセスが集中')):
        raise RuntimeError('公開サイト側のアクセス制限')
    return soup


