# ====================================================================
# 統合追加: 3連複4頭BOX 発走前購入/見送り研究 (v1.0)
# 既存の指数・取得・GitHub復元関数を改変しない。
# 新AIは年次時計55%と騎手相性20%を反映。4頭BOX期待回収率は未校正である。
# ====================================================================
BS_BASE_APP_SHA256 = "708e1baeb1469d6682a6ea30fe705ef20c0217daaf4606b4b7959966ac2bf7c8"
BS_RULE_VERSION = "top7_newai_YEARCLOCK55_JOCKEY20_lowpayout_min13_v3_20261109"
BS_MIN_ODDS = 13.0    # 研究上の仮説。的中確率が32%なら損益分岐約12.5倍、利益保証はない
BS_MIN_LEAD_MINUTES = 5
BS_MAX_MARKET_AGE_MINUTES = 20
BS_ONE_BOX_UNIT = 100   # 同条件比較に限定：4点×100円


def bs_now():
    return datetime.datetime.now(TRIO_JST)


def bs_start_time(race):
    """レース見出しに発走時刻が明記されない場合、発走前確認不可とする。"""
    day = race.get("race_date")
    if not isinstance(day, datetime.date):
        return None
    heading = unicodedata.normalize("NFKC", str(race.get("heading_raw") or ""))
    match = re.search(r"発走時刻\s*[:：]?\s*(\d{1,2})\s*時\s*(\d{1,2})\s*分", heading)
    if not match:
        return None
    h, m = (int(match.group(1)), int(match.group(2)))
    if not (0 <= h < 24 and 0 <= m < 60):
        return None
    return datetime.datetime.combine(day, datetime.time(h, m), tzinfo=TRIO_JST)


def bs_parse_source_clock(value, capture):
    """時刻の解釈を推測し過ぎない。時刻不明なら事前検証不可。"""
    value = str(value or "").strip()
    if not value:
        return None
    compact = re.fullmatch(r"(20\d{2})(\d{2})(\d{2})\s*(\d{2})(\d{2})(\d{2})?", value)
    try:
        if compact:
            a = compact.groups()
            return datetime.datetime(int(a[0]), int(a[1]), int(a[2]),
                  int(a[3]), int(a[4]), int(a[5] or 0), tzinfo=TRIO_JST)
        parsed = datetime.datetime.fromisoformat(value.replace("/", "-").replace(" ", "T", 1))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=TRIO_JST)
        return parsed.astimezone(TRIO_JST)
    except (ValueError, TypeError):
        return None


def bs_clock_audit(start, capture, win_source, trio_source):
    if start is None:
        return False, "出走表から発走時刻を確認できません"
    if capture >= start - datetime.timedelta(minutes=BS_MIN_LEAD_MINUTES):
        return False, "発走5分前の研究締切後に取得されています"
    if capture < start - datetime.timedelta(hours=24):
        return False, "取得が発走24時間以上前です"
    for label, value in (("単勝", win_source), ("3連複", trio_source)):
        source_time = bs_parse_source_clock(value, capture)
        if source_time is None:
            return False, f"{label}の提供元更新時刻が確認できません"
        minutes = (capture - source_time).total_seconds() / 60
        if not (-1 <= minutes <= BS_MAX_MARKET_AGE_MINUTES):
            return False, f"{label}の提供元更新が古い、または未来時刻です（差{minutes:.1f}分）"
        if source_time >= start:
            return False, f"{label}提供元時刻が発走後です"
    return True, "発走5分以上前・両市場の更新時刻確認済み（なお購入価格の保証ではありません）"


def bs_choose_four(race, win_market):
    """固定ルール：単勝1～7番人気の中から、新AI（年次時計55/騎手20）上位4頭。"""
    if race.get("horse_numbers_unverified") or not race.get("is_dirt_race"):
        raise ValueError("ダート条件または馬番を確認できないレースです")
    horses = race.get("horses") or []
    numbers = [int(h.get("horse_no") or 0) for h in horses]
    if not numbers or any(n < 1 or n > 18 for n in numbers) or len(set(numbers)) != len(numbers):
        raise ValueError("馬番の欠損・重複があるため選択できません")
    if not all(h.get("horse_no_verified", False) for h in horses):
        raise ValueError("出走表の馬番が完全に確認できていません")
    if set(map(int, win_market)) != set(numbers):
        raise ValueError("単勝APIの馬番と出走表が一致しません（全頭一致が必要）")
    ranks = {}
    for no in numbers:
        obj = win_market[no]
        pop = obj.get("popularity")
        if not isinstance(pop, int) or isinstance(pop, bool):
            raise ValueError("単勝人気順位が欠損しています")
        ranks[no] = pop
    if sorted(ranks.values()) != list(range(1, len(numbers) + 1)):
        raise ValueError("単勝人気が欠損・重複・不正です。推定補完しません")
    ranked = score_new_model(horses, race)
    candidate = ranked[ranked["horse_no"].astype(int).map(lambda x: ranks.get(x, 99) <= 7)].copy()
    candidate["ai_score"] = pd.to_numeric(candidate["ai_score"], errors="coerce")
    candidate = candidate[candidate["ai_score"].apply(lambda x: pd.notna(x) and np.isfinite(x))]
    candidate = candidate.sort_values(["ai_score", "horse_no"], ascending=[False, True])
    if len(candidate) < 4:
        raise ValueError("人気上位7頭の中で指数算出できた馬が4頭未満です")
    four = tuple(sorted(int(n) for n in candidate.head(4)["horse_no"]))
    return four, ranked, ranks


def bs_json_backup():
    return {"schema": "JRA_buy_skip_v1", "rule": BS_RULE_VERSION,
            "locks": st.session_state.get("bs_locks", {}),
            "snapshots": st.session_state.get("bs_snapshots", {}),
            "outcomes": st.session_state.get("bs_outcomes", {})}


def bs_resolve_race(races, rid):
    return next((r for r in races if trio_race_id(r) == rid), None)


def bs_lock_path(rid):
    return f"buy_skip_v1/{rid[:4]}/{rid}/selection.json"


def bs_outcome_path(rid):
    return f"buy_skip_v1/{rid[:4]}/{rid}/outcome.json"


def bs_record_capture(race):
    """実時間に両市場を1レース分再取得・上書き禁止で保存する。"""
    rid = trio_race_id(race)
    if not rid:
        raise ValueError("正しいnetkeibaレースIDが確定していません")
    start = bs_start_time(race)
    # データを取りに行く前から時間検証。発走後の市場情報を利用した新規選択を禁止。
    if start is None or bs_now() >= start - datetime.timedelta(minutes=BS_MIN_LEAD_MINUTES):
        raise ValueError("発走5分前までの時刻条件を確認できないため新規判定を停止しました")
    wins, win_src = win_fetch_race(rid)
    trios, trio_src, _ = trio_fetch_race_with_retry(rid)
    capture = bs_now()
    verified, audit = bs_clock_audit(start, capture, win_src, trio_src)
    old_lock = st.session_state.setdefault("bs_locks", {}).get(rid)
    # 新セッションでも過去選択は必ず尊重する。GitHub接続なしの場合は手元バックアップを使う。
    if old_lock is None:
        try:
            old_lock, _ = get_record(bs_lock_path(rid))
            if old_lock:
                st.session_state["bs_locks"][rid] = old_lock
        except Exception:
            pass
    if old_lock:
        four = tuple(sorted(int(x) for x in old_lock["selected4"]))
        ranks = {int(no): obj.get("popularity") for no, obj in wins.items()}
        model_version = old_lock.get("model_version", "")
    else:
        if not verified:
            raise ValueError("初回4頭固定には時刻検証済みの単勝・3連複オッズが必要: " + audit)
        four, _, ranks = bs_choose_four(race, wins)
        model_version = APP_VERSION + ":newAI_YEARCLOCK55_JOCKEY20_top7"
    combinations = list(itertools.combinations(four, 3))
    if any(c not in trios for c in combinations):
        raise ValueError("3連複BOX4組のオッズが揃っていません")
    odds4 = {"-".join(map(str, c)): float(trios[c]["odds"]) for c in combinations}
    if any(not np.isfinite(x) or x < 1.0 for x in odds4.values()):
        raise ValueError("3連複オッズに1.0未満などの不正値があります")
    clock_coverage = {}
    if not old_lock:
        ref_ranked = score_new_model(race.get('horses') or [],race)
        clock_coverage = {int(no):int(ref_ranked.set_index('horse_no').loc[no,'year_clock_run_count'])
                          for no in four}
    if not old_lock:
        new_lock = {"schema": "JRA_buy_skip_lock_v1", "race_id": rid,
                    "race_name": str(race.get("race_name", "")),
                    "race_date": race["race_date"].isoformat(), "selected4": list(four),
                    "locked_at_jst": capture.isoformat(timespec="seconds"),
                    "model_version": model_version, "selection_rule": BS_RULE_VERSION,
                    "base_app_sha256": BS_BASE_APP_SHA256,
                    "year_clock_model": YC_VERSION,
                    "new_ai_model": NEW_AI_VERSION,
                    "year_clock_reference_cutoff": YC_SOURCE_MAX_DATE,
                    "year_clock_matched_runs_at_lock": {str(n):clock_coverage.get(n,0) for n in four},
                    "popularity_at_lock": {str(n): int(ranks[n]) for n in four}}
        st.session_state["bs_locks"][rid] = new_lock
        old_lock = new_lock
    # 注目: これは未検証の固定ルール。期待値推定の代用品ではない。
    now_ranks = {n: wins.get(n, {}).get("popularity") for n in four}
    if not verified:
        status, reason = "判定保留", "時刻の検証が成立しないため購入判定は行いません: " + audit
    elif (old_lock.get("year_clock_model") == YC_VERSION and
          any(int(old_lock.get("year_clock_matched_runs_at_lock",{}).get(str(n),0))==0 for n in four)):
        status, reason = "判定保留（時計照合不足）", "固定した4頭の一部は年次基準時計を検証できません。強引に補完しません"
    elif any(n is None or n > 7 for n in now_ranks.values()):
        status, reason = "見送り（人気条件逸脱）", "固定4頭の一部が現在の単勝人気8位以下です。再選択はしません"
    elif min(odds4.values()) < BS_MIN_ODDS:
        status, reason = "見送り（低配当・研究ルール）", "BOX4組に13.0倍未満の組があります。低配当除外仮説による判定"
    else:
        status, reason = "研究上の購入候補（未実証）", "4組すべて13.0倍以上。利益優位性は未証明、購入推奨ではありません"
    snapshot = {"schema": "JRA_buy_skip_snapshot_v1", "race_id": rid,
                "race_name": str(race.get("race_name", "")), "race_date": race["race_date"].isoformat(),
                "start_jst": start.isoformat(), "captured_at_jst": capture.isoformat(timespec="microseconds"),
                "source_win_time": str(win_src), "source_trio_time": str(trio_src),
                "timing_verified": bool(verified), "timing_note": audit,
                "selected4": list(four), "popularity_at_capture": {str(k): v for k, v in now_ranks.items()},
                "win_odds": {str(n): {"odds": r.get("odds"), "popularity": r.get("popularity")}
                             for n, r in wins.items()},
                "trio_odds4": odds4,
                "trio_all": {"-".join(map(str, k)): {"odds": v.get("odds"), "popularity": v.get("popularity")}
                             for k, v in trios.items()},
                "decision": status, "reason": reason, "rule": old_lock.get("selection_rule",BS_RULE_VERSION),
                "year_clock_model": old_lock.get("year_clock_model", "旧モデル・年次補正未適用"),
                "year_clock_matched_runs_at_lock":old_lock.get("year_clock_matched_runs_at_lock", {}),
                "stake_yen": BS_ONE_BOX_UNIT * 4, "model_version": model_version,
                "base_app_sha256": BS_BASE_APP_SHA256,
                "saved_to_github": False}
    st.session_state.setdefault("bs_snapshots", {}).setdefault(rid, []).append(snapshot)
    # 保存パスは一意、同一スナップショットを後から更新しない。
    stamp = capture.strftime("%Y%m%dT%H%M%S%f")
    save_messages = []
    try:
        if not get_record(bs_lock_path(rid))[0]:
            put_record(bs_lock_path(rid), old_lock, overwrite=False)
        path = f"buy_skip_v1/{rid[:4]}/{rid}/snapshots/{stamp}.json"
        if put_record(path, snapshot, overwrite=False):
            snapshot["saved_to_github"] = True
            save_messages.append("GitHubへ追記保存: " + path)
        else:
            save_messages.append("同じ取得記録がGitHubに存在します")
    except Exception as exc:
        save_messages.append("GitHub保存不可: " + str(exc) + "。下のJSONバックアップを保存してください")
    return snapshot, save_messages


def bs_result_payoff(snapshot, winning, payout, special=False):
    """結果を購入・見送り共通の仮購入成績として評価。"""
    if special:
        return None
    combos = {tuple(int(x) for x in key.split("-")) for key in snapshot["trio_odds4"]}
    hit = winning in combos
    return {"hit": hit, "stake": 400, "return": int(payout) if hit else 0}


def bs_load_history_from_github(rid):
    """GitHubにある選択固定情報・スナップショットを復元。結果は別データ。"""
    lock, _ = get_record(bs_lock_path(rid))
    if not lock:
        return 0
    st.session_state.setdefault("bs_locks", {})[rid] = lock
    folder = f"buy_skip_v1/{rid[:4]}/{rid}/snapshots"
    paths = list_files(folder)
    loaded = []
    for path in paths:
        if path.endswith(".json"):
            record, _ = get_record(path)
            if record and record.get("race_id") == rid:
                loaded.append(record)
    unique = {r["captured_at_jst"]: r for r in loaded}
    st.session_state.setdefault("bs_snapshots", {})[rid] = sorted(unique.values(), key=lambda x: x["captured_at_jst"])
    outcome, _ = get_record(bs_outcome_path(rid))
    if outcome:
        st.session_state.setdefault("bs_outcomes", {})[rid] = outcome
    return len(unique)


def bs_eval_history():
    """1レースにつき発走前の最初の時刻検証済み判定を1件採用（重複計上防止）。"""
    rows = []
    for rid, records in st.session_state.get("bs_snapshots", {}).items():
        valid = [r for r in records if r.get("timing_verified") and r.get("decision") != "判定保留"]
        if not valid:
            continue
        first = sorted(valid, key=lambda r: r.get("captured_at_jst", ""))[0]
        outcome = st.session_state.get("bs_outcomes", {}).get(rid)
        if not outcome or outcome.get("special"):
            continue
        winning = trio_combo_key(outcome.get("winning_combo", ""))
        if winning is None:
            continue
        stats = bs_result_payoff(first, winning, outcome.get("payout_yen100", 0))
        rows.append({"レースID": rid, "開催日": first["race_date"], "レース": first["race_name"],
                     "判定": first["decision"], "モデル版":first.get("model_version","未記録"),
                     "年次時計版":first.get("year_clock_model","旧モデル"), "的中": stats["hit"],
                     "仮購入額": stats["stake"], "仮払戻額": stats["return"],
                     "発走前取得JST": first["captured_at_jst"],
                     "採用4頭": "-".join(map(str, first["selected4"]))})
    return pd.DataFrame(rows)


